wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, Intent, LlmError};

const MAX_QUESTION_CHARS: usize = 512;
const MAX_ROUNDS: usize = 4;
const MAX_PROMPT_BYTES: usize = 64 * 1024;

const SYSTEM: &str = "You are a customer-support assistant. Answer the question \
using the knowledge snippets provided. If you need more information, call the \
lookup tool with a query.";

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing question",
        Intent::TechnicalSupport => "technical support",
        Intent::AccountChange => "account change",
        Intent::GeneralInquiry => "general inquiry",
        Intent::Unknown => "unknown",
    }
}

fn fail(message: impl Into<String>) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.into(),
    })
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Defensive: the node's `requires` already guarantees this bound.
        if ctx.question.chars().count() > MAX_QUESTION_CHARS {
            return fail("question exceeds 512 characters");
        }

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        for snippet in &ctx.knowledge {
            prompt.push_str("\nKnowledge: ");
            prompt.push_str(snippet);
        }

        for _ in 0..MAX_ROUNDS {
            if prompt.len() > MAX_PROMPT_BYTES {
                return fail("prompt grew past the size bound");
            }

            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(request) => {
                    if request.tool != "lookup" {
                        return fail(format!("tool not in scope: {}", request.tool));
                    }
                    let results = kb_read::lookup(&request.query);
                    prompt.push_str("\nLookup ");
                    prompt.push_str(&request.query);
                    prompt.push(':');
                    for result in &results {
                        prompt.push_str("\n  ");
                        prompt.push_str(result);
                    }
                }
            }
        }

        fail("tool-call limit reached without an answer")
    }
}

export!(Node);
```

